import { describe, expect, it, jest } from '@jest/globals';
import { ToolRegistry } from './registry.js';
import { ToolDefinition } from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => ({ result: 'success' }));

    registry.register({
      name: 'testTool',
      description: 'A test tool',
      inputSchema: {
        type: 'object',
        properties: {
          location: { type: 'string' }
        },
        required: ['location']
      },
      executor
    });

    const response = await registry.execute('testTool', {});

    expect(response).toEqual({ result: expect.stringContaining('location') });
    expect(executor).toHaveBeenCalledTimes(0);
  });
});
